class Solution {int[]parent;int find(int u){while(parent[u]!=u){parent[u]=parent[parent[u]];u=parent[u];}return u;}public long solve(int n,int[][]edges){if(n<2)return 0;parent=new int[n];for(int i=0;i<n;i++)parent[i]=i;Arrays.sort(edges,(a,b)->Integer.compare(a[2],b[2]));long total=0;int joined=0;for(int[]e:edges){int a=find(e[0]),b=find(e[1]);if(a!=b){parent[a]=b;total+=e[2];if(++joined==n-1)return total;}}return -1;}}